import numpy as np
from scipy.optimize import curve_fit

d = np.genfromtxt('/app/spectrum.csv', delimiter=',', names=True)
x = np.array(d[d.dtype.names[0]])
y = np.array(d['intensity'])

def lor(x, x0, gamma, amp, off):
    return amp*gamma**2/((x-x0)**2+gamma**2) + off

def fit(lo, hi, guess):
    m = (x>=lo)&(x<=hi)
    xs, ys = x[m], y[m]
    p, cov = curve_fit(lor, xs, ys, p0=guess, maxfev=100000)
    res = lor(xs, *p) - ys
    rms = np.sqrt(np.mean(res**2))
    return p, rms, len(xs)

peaks = {
 'D':  [(1200,1500),(1250,1470),(1280,1450),(1300,1420),(1150,1550)],
 'G':  [(1450,1700),(1480,1680),(1500,1660),(1400,1750)],
 '2D': [(2450,2950),(2500,2900),(2550,2850),(2400,3000),(2600,2780)],
}
guess = {'D': (1350,15,1400,950), 'G': (1581,15,6600,950), '2D': (2685,15,13000,900)}
for name, wins in peaks.items():
    print('===', name)
    for (lo,hi) in wins:
        try:
            p, rms, n = fit(lo,hi,guess[name])
            print('win %6.1f-%6.1f n=%4d  x0=%9.3f gamma=%8.3f amp=%10.2f off=%8.2f rms=%8.3f' % (lo,hi,n,p[0],p[1],p[2],p[3],rms))
        except Exception as e:
            print('win', lo, hi, 'FAILED', e)
